* --- Stimulus ---
* Vcm provides DC 0.9V for AC/OP, and a pulse for TRAN
Vcm vp 0 DC 0.9 AC 1 PULSE(0.4 1.4 10n 1n 1n 1u 2u)

* --- Analysis ---
.control
  * 1. DC Operating Point (Power)
  op
  let power = -i(Vdd) * 1.8
  print power

  * 2. AC Analysis (Open-Loop Gain, Phase Margin, UGF)
  * Rbig1=100M, Cbig1=100uF (default in netlist) sets up open-loop AC with closed-loop DC
  ac dec 100 1 1G
  let gain_db = vdb(Vout)
  let phase = 180/PI * cph(v(Vout))

  meas ac open_loop_gain find gain_db at=10
  meas ac unity_gain_freq when gain_db=0 fall=1
  meas ac phase_at_ugf find phase when gain_db=0 fall=1
  let phase_margin = phase_at_ugf + 180
  print open_loop_gain unity_gain_freq phase_margin

  * 3. Transient Analysis (Slew Rate)
  * Reconfigure as unity-gain buffer by altering feedback components
  alter Rbig1 1e-3
  alter Cbig1 1e-15

  tran 1n 2u
  meas tran t_start when v(Vout)=0.6 rise=1
  meas tran t_end when v(Vout)=1.2 rise=1
  let slew_rate_V_us = (1.2 - 0.6) / (t_end - t_start) / 1e6
  print slew_rate_V_us
.endc
.end

